18	// Client is an authenticated HTTP client for the Entire API.
19	// It attaches the bearer token to all outgoing requests via the Authorization header.
20	type Client struct {
21		httpClient *http.Client
22		baseURL    string
23	}
24	
25	// NewClient creates a new authenticated API client with an explicit bearer token.
26	func NewClient(token string) *Client {
27		return &Client{
28			httpClient: &http.Client{
29				Transport: &bearerTransport{
30					token: token,
31					base:  http.DefaultTransport,
32				},
33			},
34			baseURL: BaseURL(),
35		}
36	}
37	
38	// bearerTransport is an http.RoundTripper that injects the Authorization header.
39	type bearerTransport struct {
40		token string
41		base  http.RoundTripper
42	}
43	
44	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
45		// Clone the request to avoid mutating the caller's request.
46		r := req.Clone(req.Context())
47		r.Header.Set("Authorization", "Bearer "+t.token)
48		r.Header.Set("User-Agent", userAgent)
49		if r.Header.Get("Accept") == "" {
50			r.Header.Set("Accept", "application/json")
51		}
52		resp, err := t.base.RoundTrip(r)
53		if err != nil {
54			return nil, fmt.Errorf("round trip: %w", err)
55		}
56		return resp, nil
57	}
58	
59	// Get sends an authenticated GET request to the given API-relative path.
60	func (c *Client) Get(ctx context.Context, path string) (*http.Response, error) {
61		return c.do(ctx, http.MethodGet, path, nil)
62	}
63	
64	// Post sends an authenticated POST request with a JSON body to the given API-relative path.
65	func (c *Client) Post(ctx context.Context, path string, body any) (*http.Response, error) {
66		var reader io.Reader
67		if body != nil {
68			data, err := json.Marshal(body)
69			if err != nil {
70				return nil, fmt.Errorf("marshal request body: %w", err)
71			}
72			reader = bytes.NewReader(data)
73		}
74		return c.do(ctx, http.MethodPost, path, reader)
75	}
76	
77	// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
78	func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
79		var reader io.Reader
80		if body != nil {
81			data, err := json.Marshal(body)
82			if err != nil {
83				return nil, fmt.Errorf("marshal request body: %w", err)
84			}
85			reader = bytes.NewReader(data)
86		}
87		return c.do(ctx, http.MethodPut, path, reader)
88	}
89	
90	// Patch sends an authenticated PATCH request with a JSON body to the given API-relative path.
91	func (c *Client) Patch(ctx context.Context, path string, body any) (*http.Response, error) {
92		var reader io.Reader
93		if body != nil {
94			data, err := json.Marshal(body)
95			if err != nil {
96				return nil, fmt.Errorf("marshal request body: %w", err)
97			}
98			reader = bytes.NewReader(data)
99		}
100		return c.do(ctx, http.MethodPatch, path, reader)
101	}
102	
103	// Delete sends an authenticated DELETE request to the given API-relative path.
104	func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
105		return c.do(ctx, http.MethodDelete, path, nil)
106	}
107	
108	func (c *Client) do(ctx context.Context, method, path string, body io.Reader) (*http.Response, error) {
109		endpoint, err := ResolveURLFromBase(c.baseURL, path)
110		if err != nil {
111			return nil, fmt.Errorf("resolve URL %s: %w", path, err)
112		}
113	
114		req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
115		if err != nil {
116			return nil, fmt.Errorf("create request: %w", err)
117		}
118	
119		if body != nil {
120			req.Header.Set("Content-Type", "application/json")
121		}
122	
123		resp, err := c.httpClient.Do(req)
124		if err != nil {
125			return nil, fmt.Errorf("%s %s: %w", method, path, err)
126		}
127		return resp, nil
128	}
129	
130	// DecodeJSON reads the response body and decodes it into dest.
131	// It limits the body size to protect against unbounded reads.
132	// The caller is responsible for closing resp.Body.
133	func DecodeJSON(resp *http.Response, dest any) error {
134		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
135		if err != nil {
136			return fmt.Errorf("read response body: %w", err)
137		}
138	
139		if err := json.Unmarshal(body, dest); err != nil {
140			return fmt.Errorf("decode JSON response: %w", err)
141		}
142	
143		return nil
144	}
145	
146	// ErrorResponse represents a standard API error response.
147	type ErrorResponse struct {
148		Error string `json:"error"`
149	}
150	
151	// CheckResponse returns an error if the response status code indicates failure.
152	// For non-2xx responses, it reads and parses the error message from the body.
153	// The caller is responsible for closing resp.Body.
154	func CheckResponse(resp *http.Response) error {
155		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
156			return nil
157		}
158	
159		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
160		if err != nil {
161			return fmt.Errorf("API error: status %d", resp.StatusCode)
162		}
163	
164		var apiErr ErrorResponse
165		if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
166			return fmt.Errorf("API error: %s (status %d)", apiErr.Error, resp.StatusCode)
167		}
168	
169		text := strings.TrimSpace(string(body))
170		if text != "" {
171			return fmt.Errorf("API error: %s (status %d)", text, resp.StatusCode)
172		}
173	
174		return fmt.Errorf("API error: status %d", resp.StatusCode)
175	}
