82			fmt.Fprintln(outW)
83	
84			if err := openURL(ctx, approvalURL); err != nil {
85				fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
86				fmt.Fprintf(outW, "Open the approval URL in your browser to continue and enter the generated device code: %s\n", approvalURL)
87			}
88		} else {
89			fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
90		}
91	
92		fmt.Fprintln(outW, "Waiting for approval...")
93	
94		token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
95		if err != nil {
96			return fmt.Errorf("complete login: %w", err)
97		}
98	
99		store := auth.NewStore()
100	
101		if err := store.SaveToken(client.BaseURL(), token); err != nil {
102			return fmt.Errorf("save auth token: %w", err)
103		}
104	
105		fmt.Fprintln(outW, "Login complete.")
106		return nil
107	}
108	
109	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (string, error) {
110		expiry := time.Duration(expiresIn) * time.Second
111		if expiry <= 0 || expiry > maxExpiresIn {
112			expiry = maxExpiresIn
113		}
114		deadline := time.Now().Add(expiry)
115		pollInterval := interval
116		if pollInterval <= 0 {
117			pollInterval = fallbackDeviceAuthPollInterval
118		}
119	
120		consecutiveErrors := 0
121	
122		for {
123			if time.Now().After(deadline) {
124				return "", errors.New("device authorization expired")
125			}
126	
127			result, err := poller.PollDeviceAuth(ctx, deviceCode)
128			if err != nil {
129				consecutiveErrors++
130				if consecutiveErrors >= maxTransientErrors {
131					return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
132				}
133				// Transient error — wait and retry.
134				select {
135				case <-ctx.Done():
136					return "", fmt.Errorf("wait for approval: %w", ctx.Err())
137				case <-time.After(pollInterval):
138				}
139				continue
140			}
141			consecutiveErrors = 0
142	
143			switch result.Error {
144			case "":
145				if result.AccessToken == "" {
146					return "", errors.New("device authorization completed without a token")
147				}
148				return result.AccessToken, nil
149			case "authorization_pending":
150				// no-op, will sleep and retry below
151			case "slow_down":
152				pollInterval += slowDownBackoff
153				if pollInterval > maxPollInterval {
154					pollInterval = maxPollInterval
155				}
156			case "access_denied":
157				return "", errors.New("device authorization denied")
158			case "expired_token":
159				return "", errors.New("device authorization expired")
160			default:
161				return "", fmt.Errorf("device authorization failed: %s", result.Error)
162			}
163	
164			select {
165			case <-ctx.Done():
166				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
167			case <-time.After(pollInterval):
168			}
169		}
170	}
171	
172	// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
173	// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
174	// Returns ctx.Err() if the context is cancelled before the user presses Enter.
175	func waitForEnter(ctx context.Context) error {
176		tty, err := os.Open("/dev/tty")
177		if err != nil {
178			return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
179		}
180	
181		done := make(chan error, 1)
182		go func() {
183			reader := bufio.NewReader(tty)
184			_, err := reader.ReadString('\n')
185			done <- err
186		}()
187	
188		select {
189		case <-ctx.Done():
190			// Close tty to unblock the reading goroutine.
191			_ = tty.Close()
192			return fmt.Errorf("interrupted: %w", ctx.Err())
193		case <-done:
194			_ = tty.Close()
195			return nil
196		}
197	}
198	
199	func openBrowser(ctx context.Context, browserURL string) error {
200		u, err := url.Parse(browserURL)
201		if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
202			return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
203		}
204	
205		var command string
206		var args []string
207	
208		switch runtime.GOOS {
209		case "darwin":
210			command = "open"
211			args = []string{browserURL}
212		case "linux":
213			command = "xdg-open"
214			args = []string{browserURL}
215		case "windows":
216			command = "cmd"
217			args = []string{"/c", "start", "", browserURL}
218		default:
219			return fmt.Errorf("unsupported platform %s", runtime.GOOS)
220		}
221	
222		cmd := exec.CommandContext(ctx, command, args...)
223		if err := cmd.Start(); err != nil {
224			return fmt.Errorf("start browser command %q: %w", command, err)
225		}
226	
227		if err := cmd.Process.Release(); err != nil {
228			return fmt.Errorf("release browser process: %w", err)
229		}
230	
231		return nil
232	}
233

