package cli

import (
	"context"
	"fmt"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/spf13/cobra"
)

// logoutTokenStore abstracts keyring access so runLogout can be unit-tested
// without hitting the real OS keyring.
type logoutTokenStore interface {
	GetToken(baseURL string) (string, error)
	DeleteToken(baseURL string) error
}

// logoutRevokeFunc revokes the supplied token server-side. It mirrors the
// openURL injection pattern in login.go so tests can replace the real HTTP call.
type logoutRevokeFunc func(ctx context.Context, token string) error

func newLogoutCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "logout",
		Short: "Log out of Entire",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runLogout(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(),
				auth.NewStore(), defaultRevokeCurrentToken, api.BaseURL())
		},
	}
}

func defaultRevokeCurrentToken(ctx context.Context, token string) error {
	return api.NewClient(token).RevokeCurrentToken(ctx)
}

func runLogout(ctx context.Context, outW, errW io.Writer, store logoutTokenStore, revoke logoutRevokeFunc, baseURL string) error {
	token, err := store.GetToken(baseURL)
	if err != nil {
		// Fall through to the local delete: we still want the keyring entry
		// gone, even if we couldn't read it well enough to revoke server-side.
		fmt.Fprintf(errW, "Warning: failed to read token before revocation: %v\n", err)
	}
	if token != "" {
		if err := revoke(ctx, token); err != nil {
			// Best-effort: a transient network error or a server-side 401 for
			// an already-invalid token shouldn't block local logout.
			fmt.Fprintf(errW, "Warning: server-side token revocation failed: %v\n", err)
		}
	}

	if err := store.DeleteToken(baseURL); err != nil {
		return fmt.Errorf("remove auth token: %w", err)
	}

	fmt.Fprintln(outW, "Logged out.")
	return nil
}

package cli

import (
	"bytes"
	"context"
	"errors"
	"strings"
	"testing"
)

type mockTokenStore struct {
	tokens     map[string]string
	deleted    map[string]bool
	getErr     error
	deleteErr  error
	getCalls   int
	deleteCall int
}

func newMockTokenStore() *mockTokenStore {
	return &mockTokenStore{
		tokens:  make(map[string]string),
		deleted: make(map[string]bool),
	}
}

func (m *mockTokenStore) GetToken(baseURL string) (string, error) {
	m.getCalls++
	if m.getErr != nil {
		return "", m.getErr
	}
	return m.tokens[baseURL], nil
}

func (m *mockTokenStore) DeleteToken(baseURL string) error {
	m.deleteCall++
	if m.deleteErr != nil {
		return m.deleteErr
	}
	m.deleted[baseURL] = true
	return nil
}

func TestRunLogout_RevokesServerSideThenDeletesLocally(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = "tok123"

	var gotToken string
	revoke := func(_ context.Context, token string) error {
		gotToken = token
		return nil
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, "https://entire.io")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if gotToken != "tok123" {
		t.Errorf("revoke called with token %q, want %q", gotToken, "tok123")
	}
	if !store.deleted["https://entire.io"] {
		t.Fatal("expected token to be deleted for https://entire.io")
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
	if errOut.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", errOut.String())
	}
}

func TestRunLogout_NoTokenSkipsRevoke(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore() // no token stored

	revokeCalled := false
	revoke := func(context.Context, string) error {
		revokeCalled = true
		return nil
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, "https://entire.io")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if revokeCalled {
		t.Fatal("revoke should not be called when no local token exists")
	}
	if !store.deleted["https://entire.io"] {
		t.Fatal("expected DeleteToken to be called even when no token was stored")
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
}

func TestRunLogout_RevokeFailureWarnsButSucceeds(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = "tok123"

	revoke := func(context.Context, string) error {
		return errors.New("connection refused")
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, "https://entire.io")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !store.deleted["https://entire.io"] {
		t.Fatal("local token should still be deleted when server revoke fails")
	}
	if !strings.Contains(errOut.String(), "server-side token revocation failed") {
		t.Fatalf("stderr = %q, want warning about revoke failure", errOut.String())
	}
	if !strings.Contains(errOut.String(), "connection refused") {
		t.Fatalf("stderr = %q, want underlying error message", errOut.String())
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
}

func TestRunLogout_GetTokenErrorWarnsAndFallsThrough(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.getErr = errors.New("keyring locked for read")

	revokeCalled := false
	revoke := func(context.Context, string) error {
		revokeCalled = true
		return nil
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, "https://entire.io")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if revokeCalled {
		t.Fatal("revoke should not be called when token read fails")
	}
	if !store.deleted["https://entire.io"] {
		t.Fatal("DeleteToken should still be attempted after GetToken failure")
	}
	if !strings.Contains(errOut.String(), "failed to read token before revocation") {
		t.Fatalf("stderr = %q, want warning about read failure", errOut.String())
	}
}

func TestRunLogout_ReturnsErrorOnDeleteFailure(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = "tok123"
	store.deleteErr = errors.New("keyring locked")

	revoke := func(context.Context, string) error { return nil }

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, "https://entire.io")
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if !strings.Contains(err.Error(), "keyring locked") {
		t.Fatalf("error = %q, want to contain %q", err.Error(), "keyring locked")
	}
	if strings.Contains(out.String(), "Logged out.") {
		t.Fatal("should not print success message when local delete fails")
	}
}

func TestLogoutCmd_IsRegistered(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	found := false
	for _, c := range root.Commands() {
		if c.Use == "logout" {
			found = true
			break
		}
	}
	if !found {
		t.Fatal("logout command not registered on root")
	}
}

